\label{th 3.1.1}
Assume that $\Omega$ is an open, bounded and connected domain of
class $C^2$ and $\alpha\in(0,1)$. Then we have:

\noindent
{\bf Existence}: Assume that $f$ satisfies (H1) and (H2), then there exists $\tau_0(\alpha)\in (-1,0)$ such that for every $p$ satisfying
\begin{equation}\label{pp1}
1+2\alpha<p<1-\frac{2\alpha}{\tau_0(\alpha)},
\end{equation}
the equation (\ref{eteo1}) possesses at least one solution 
 $u$ satisfying
\begin{equation}\label{3.1.5}
0<\liminf_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{\frac{2\alpha}{p-1}}\le\limsup_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{\frac{2\alpha}{p-1}} <+\infty.
\end{equation}
{\bf Uniqueness}: If $f$ further satisfies $f\ge 0$ in $\Omega$, then $u>0$ in $\Omega$ and $u$ is the unique
solution of (\ref{eteo1}) satisfying (\ref{3.1.5}).

\noindent
{\bf Nonexistence}: If $f$ satisfies (H1) and (H2$^*$), then in the following three cases:
\begin{itemize}
\item[i)] For any $\tau\in(-1,0)\setminus\{-\frac{2\alpha}{p-1},\
\tau_0(\alpha)\}$ and $p$ satisfying (\ref{pp1}) or
\item[ii)] For any $\tau\in(-1,0)$ and 
\begin{equation}\label{pp2}
p\ge 1-\frac{2\alpha}{\tau_0(\alpha)}\mbox{ or}
\end{equation}
\item[iii)] For any $\tau\in(-1,0)\setminus\{\tau_0(\alpha)\}$ and 
\begin{equation}\label{pmalpha}
1<p\le 1+2\alpha,
\end{equation}
\end{itemize}
equation  (\ref{eteo1}) does not have a solution $u$ satisfying
\begin{equation}\label{1.7}
0<\liminf_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{-\tau}\le\limsup_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{-\tau} <+\infty.
\end{equation} 
\noindent
{\bf Special existence for $\tau=\tau_0(\alpha)$.}
 Assume $f(x)\equiv0,\ x\in\Omega$ and
that
\begin{equation}\label{observartion}
\max\{1-\frac{2\alpha}{\tau_0(\alpha)}+\frac{\tau_0(\alpha)+1}{\tau_0(\alpha)},1\}<p<1-\frac{2\alpha}{\tau_0(\alpha)}.
\end{equation}
Then, there exist constants $C_1\geq 0$ and $C_2>0$, such that for any $t>0$ there is  a  positive solution $u$ of equation
(\ref{eteo1})  satisfying
\begin{equation}\label{obs3.1.5}
C_1d(x)^{\min\{\tau_0(\alpha)p+2\alpha,0\}}\leq td(x)^{\tau_0(\alpha)}-u(x)\le
C_2 d(x)^{\min\{\tau_0(\alpha)p+2\alpha,0\}}.
\end{equation}

\label{th 3.1.2}
Assume that $\Omega$ is an open, bounded and connected domain of
class $C^2$. Assume that $f$ satisfies (H1)  and let $\alpha\in(0,1)$ then we have:

$(i)$ (weak source) If $f$ satisfies (H3) with 
\begin{equation}\label{gamma1}
-2\alpha-\frac{2\alpha}{p-1}\leq\gamma<-2\alpha,
\end{equation}
then, for every $p$ such that (\ref{pp2}) holds,



equation  (\ref{ecbir2a}) possesses at
least one solution $u$,  with asymptotic behavior near the boundary given by
\begin{equation}\label{3.1.10}
0<\liminf_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{-\gamma-2\alpha}\le\limsup_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{-\gamma-2\alpha} <+\infty.
\end{equation}
$(ii)$ (strong source)  If $f$ satisfies (H3) with 
\begin{equation}\label{gamma2}
-1-2\alpha<\gamma<-2\alpha-\frac{2\alpha}{p-1}
\end{equation}
then, for every $p$ such that
\begin{equation}\label{pp4} 
p>1+2\alpha,
 \end{equation}
 equation  (\ref{ecbir2a}) possesses at
least one solution $u$,  with asymptotic behavior near the boundary given by 
\begin{equation}\label{3.1.11}
0<\liminf_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{-\frac{\gamma}{p}}\le\limsup_{x\in\Omega,x\to\partial\Omega}
u(x)d(x)^{-\frac{\gamma}{p}} <+\infty.
\end{equation}

\label{th 1.1}
Assume that $\Omega$ is an open, bounded and connected domain of
class $C^2$, $\alpha\in(0,1)$ and
   $f$ satisfies (H1) and $f\ge 0$. Then  we have
\begin{itemize}
\item[i)] (weak source)  the solution of (\ref{ecbir2a}) satisfying  (\ref{3.1.10}) is positive and unique, and 
\item[ii)] (strong source)  the solution of (\ref{ecbir2a}) satisfying (\ref{3.1.11}) is positive and unique.
\end{itemize}

\label{nonexistence}
Assume that $\Omega$ is an open, bounded and connected domain of
class $C^2$, $\alpha\in(0,1)$ and $f$ satisfies
$(H1)$, $(H3)$ and $f\ge 0$. Then we have


\begin{itemize}
\item[i)] (weak source) Suppose that $p$ satisfies (\ref{pp2}), $\gamma$ satisfies (\ref{gamma1}) and $\tau\in(-1,0)\setminus\{\gamma+2\alpha\}$. Then 



equation (\ref{eteo1}) does not have a solution  $u$ satisfying (\ref{1.7}).  










\item[ii)]  (strong source) Suppose that $p$ satisfies (\ref{pp4}), $\gamma$ satisfies (\ref{gamma2}) and $\tau\in(-1,0)\setminus\{\frac\gamma p\}$. Then, 
equation (\ref{eteo1}) does not have a solution  $u$ satisfying (\ref{1.7}).  
\end{itemize}

\label{th 3.2.3}
 Suppose that ${\mathcal{O}}$ is an open, bounded and $C^2$ domain,  $g:{\mathcal{O}}^c\to\mathbb{R}$ satisfies   $(G)$, $f:\bar{{\mathcal{O}}}\to\mathbb{R}$ is continuous, $f\in C^\beta_{loc}({\mathcal{O}})$, with $\beta\in(0,1)$,  and $p>1$.
Then there exists a classical solution $u$ of
\begin{equation}\label{3.2.4}
\left\{ \arraycolsep=1pt
\begin{array}{lll}
 (-\Delta)^{\alpha} u(x)+|u|^{p-1}u(x)=f(x),\ \ \ \ &
x\in{\mathcal{O}},\\[2mm]
u(x)=g(x),\ &x\in{\mathcal{O}}^c,
\end{array}
\right.
\end{equation}
which is continuous in $\bar{{\mathcal{O}}}$.

\label{lm 3.2.2}
Suppose that ${\mathcal{O}}$ is an open, bounded and $C^2$ domain, $f:\bar{{\mathcal{O}}}\to\mathbb{R}$ is continuous  and $C>0$. Then there
exist a classical solution of
\begin{eqnarray}
\left\{ \arraycolsep=1pt
\begin{array}{lll}\label{xxx}
 (-\Delta)^{\alpha} u(x)+Cu(x)=f(x),\ \ \ \ &
x\in{\mathcal{O}},\\[2mm]
u(x)=0,\ &x\in{\mathcal{O}}^c,
\end{array}
\right.
\end{eqnarray}
which is continuous in $\bar{{\mathcal{O}}}$.

\label{pr 3.3.2}
 For every  $\alpha\in(0,1)$  there exists a unique $\tau_0(\alpha)\in (-1,0)$ such that
$C(\tau_0(\alpha))=0$ and 
\begin{equation}\label{signotau}
C(\tau)(\tau-\tau_0(\alpha))<0,\quad\mbox{for all}\,\, \tau\in (-1,0)\setminus\{\tau_0(\alpha)\}.
\end{equation}
Moreover, the function $\tau_0$ satisfies
\begin{equation}\label{1.3.2}
\lim_{\alpha\to1^-}\tau_0(\alpha)=0\quad\mbox{and}\quad
\lim_{\alpha\to0^+}\tau_0(\alpha)=-1.
\end{equation}

By compactness we prove that the corresponding inequality holds in a neighborhood of any point $\bar x\in\partial\Omega$ and  without loss of generality we may assume that $\bar
x=0$. For  a given $0<\eta\le \delta$, we define
$$
Q_\eta=\{z=(z_1,z')\in\mathbb{R}\times\mathbb{R}^{N-1}, |z_1|<\eta,|z'|<\eta\}$$
and  $Q_\eta^+=\{z\in
Q_\eta,z_1>0\}$.
Let $\varphi:\mathbb{R}^{N-1}\to\mathbb{R}$  be a $C^2$
function such that $(z_1, z')\in \Omega\cap Q_\eta$ if and only if $z_1\in (\varphi(z'),\eta)$ and 
 moreover,   $(\varphi(z'),z')\in\partial\Omega$ for all $|z'|<\eta$. We further assume that  $(-1,0,\cdot\cdot\cdot,0)$ is the outer normal
vector of $\Omega$ at $\bar x$.  

In the proof of our inequalities, we let 
$x=(x_1,0)$, with $x_1\in(0,\eta/4)$, be then a generic point in $A_{\eta/4}$. We observe that $|x-\bar
x|=d(x)=x_1$.
By definition we have
\begin{eqnarray}
-(-\Delta)^\alpha V_\tau(x)=\frac12 \int_{Q_{
\eta}}\frac{\delta(V_\tau,x,y)}{|y|^{N+2\alpha}}dy+\frac12 \int_{\mathbb{R}^N\setminus
Q_{ \eta}}\frac{\delta(V_\tau,x,y)}{|y|^{N+2\alpha}}dy \label{cotadelta}
\end{eqnarray}
and we see that 
\begin{equation}\label{cotadelta1}
|\int_{\mathbb{R}^N\setminus
Q_{ \eta}}\frac{\delta(V_\tau,x,y)}{|y|^{N+2\alpha}}dy|
\le c|x|^\tau,
\end{equation}
where the constant $c$ is independent of $x$. Thus we only need to study the asymptotic behavior of the first integral, that from now on we denote by $E(x_1)$.


Our first goal is to get a lower bound for $E(x_1)$. For that purpose we first notice that, since  $\tau\in(-1,0)$, we have that


\begin{equation}\label{1.3.5}
d(z)^\tau\ge |z_1-\varphi(z')|^\tau,\quad\mbox{for all}\quad  z\in Q_\delta\cap\Omega.
\end{equation}


 Now we assume that  $0<\eta\le \delta/2$,  then for all
$y\in Q_{\eta}$ we have 
 $x\pm y\in Q_\delta $. Thus  $x\pm y\in \Omega\cap Q_\delta$ if and only if
$\varphi(\pm y')<x_1\pm y_1<\delta$ and $|y'|<\delta$.
 Then, by  (\ref{1.3.5}),
we have  that 
\begin{eqnarray}\label{DES1}
\quad V_\tau(x+ y)= d(x+ y)^\tau\ge[x_1+ y_1-\varphi(y')]^\tau,\quad x+y\in Q_{\delta}\cap\Omega 
\end{eqnarray}
and 


\begin{eqnarray}\label{DES2} 
\quad V_\tau(x- y)=d(x- y)^\tau\ge[x_1- y_1-\varphi( -y')]^\tau, \quad x-y\in Q_{\delta}\cap\Omega. 
\end{eqnarray}
  On the other
side, for $y\in Q_{\eta}$ we have that if $x\pm y\in Q_\delta\cap\Omega^c$ then, by definition of $V_\tau$, we have
$V_\tau(x\pm y)=0.$
Now, for  $y\in Q_\eta$ we define the intervals 
\begin{equation}\label{I1}I_+=(\varphi( y')-x_1,\eta-x_1)\quad\mbox{and} \quad I_-=(x_1-\eta,x_1-\varphi(
-y'))
\end{equation}
and the functions
\begin{eqnarray}
I(y)&=&\chi_{I_+}(y_1)|x_1+y_1-\varphi(y')|^{\tau}+\chi_{I_-}(y_1)|x_1-y_1-\varphi(-y')|^{\tau}-2x_1^\tau,~~~~~\nonumber\\




J(y_1)&=&\chi_{(x_1-\eta,x_1)}(y_1)|x_1-y_1|^{\tau}+\chi_{(-x_1,\eta-x_1)}(y_1)|x_1+y_1|^{\tau}-2x_1^\tau, \nonumber \\
I_1(y)&=&\{ \chi_{I_+}(y_1) -\chi_{(-x_1,\eta-x_1)}(y_1)\} |x_1+y_1|^\tau,
 \nonumber\\
 \nonumber I_2(y)&=&
 \chi_{I_+}(y_1) (|x_1+y_1-\varphi(y')|^\tau - 
 |x_1+y_1|^\tau\}), 
 \end{eqnarray}
where $\chi_A$ denotes the characteristic function of the set $A$. Then, using these definitions and inequalities (\ref{DES1}) and (\ref{DES2}), we have that
\begin{eqnarray}\label{Ex1}
\quad E(x_1)\ge \int_{Q_{\eta}} \frac{I(y)}{|y|^{N+2\alpha}}dy=\int_{Q_{\eta}} \frac{J(y_1)}{|y|^{N+2\alpha}}dy+E_1(x_1)+E_2(x_1),
\end{eqnarray}
where 
\begin{equation}\label{Ei}
E_i(x_1)=\int_{Q_{\eta}} \frac{I_i(y)+I_{-i}(y)}{|y|^{N+2\alpha}}dy,\quad i=1,2.
\end{equation}

















Here we have considered that 
$$
I_{-1}(y)=\{ \chi_{I_-}(y_1) -\chi_{(x_1-\eta,x_1)}(y_1)\} |x_1-y_1|^\tau
$$
and
$$
 I_{-2}(y)=
 \chi_{I_-}(y_1) (|x_1-y_1-\varphi(-y')|^\tau - 
 |x_1-y_1|^\tau\}),
$$
 for  $y=(y_1,y')\in\mathbb{R}^N$.
We start studying  the first integral in the right hand side in (\ref{Ex1}). Changing variables we see that
$$
\int_{Q_{\eta}}\frac{J(y_1)}{|y|^{N+2\alpha}}dy
=x_1^{\tau-2\alpha}\int_{Q_{\frac{\eta}{x_1}}}    \frac{J(x_1z_1)x_1^{-\tau}}{|z|^{N+2\alpha}}dz= 2x_1^{\tau-2\alpha}(R_1-R_2),

$$



where
$$
R_1=\int_{Q_{\frac{\eta}{x_1}}^+}\frac{\chi_{(0,1)}(z_1)|1-z_1|^{\tau}
+(1+z_1)^{\tau}-2}{|z|^{N+2\alpha}}dz
$$
and
$$
R_2=\int_{Q_{\frac{\eta}{x_1}}^+}
\frac{\chi_{(\frac{\eta}{x_1}-1,\frac{\eta}{x_1})}(z_1)(1+z_1)^{\tau}}{|z|^{N+2\alpha}}dz.
$$
Next we estimate these last two integrals. For $R_1$ we see that, for appropriate positive constants $c_1$ and $c_2$ 
 \begin{eqnarray*}
&&\int_{\mathbb{R}^N_+}\frac{\chi_{(0,1)}(z_1)|1-z_1|^{\tau}+(1+z_1)^{\tau}-2}{|z|^{N+2\alpha}}dz\\
&=&\int_0^{+\infty}\frac{\chi_{(0,1)}(z_1)|1-z_1|^{\tau}+(1+z_1)^{\tau}-2}{z_1^{1+2\alpha}}dz_1
\int_{\mathbb{R}^{N-1}}\frac{1}{(|z'|^2+1)^{\frac{N+2\alpha}{2}}}dz'
\\
&=&c_1\,C(\tau)
\end{eqnarray*}
and 
 \begin{eqnarray*}
 \int_{(Q_{\frac{\eta}{x_1}}^+)^c}\frac{\chi_{(0,1)}(z_1)|1-z_1|^{\tau}
+(1+z_1)^{\tau}-2}{|z|^{N+2\alpha}}dz =-c_2\,x_1^{2\alpha}(1+ o(1)).
\end{eqnarray*} 
Consequently we have, for some constant  $c$ that
 \begin{eqnarray}\label{R1}
 R_1=c_1(C(\tau)+cx_1^{2\alpha}+ o(x_1^{2\alpha})).
\end{eqnarray} 
For $R_2$ we have that 
\begin{eqnarray} \quad R_2\label{R2}


&=&\int_{\frac{\eta}{x_1}-1}^{\frac{\eta}{x_1}}\frac{(1+z_1)^{\tau}}{z_1^{1+2\alpha}}
\int_{B_{\frac{\eta}{x_1}}}\frac1{(1+|z'|^2)^{\frac{N+2\alpha}2}}dz'dz_1\le 


c_3x_1^{2\alpha-\tau+1},
\end{eqnarray}
where $c_3>0$. Here and in what follows we denote by $B_\sigma$ the ball of radius $\sigma$ in $\mathbb{R}^{N-1}$.
From (\ref{R1}) and (\ref{R2}) we then conclude that
\begin{eqnarray}\label{EQ}
\int_{Q_{\eta}}\frac{J(y_1)}{|y|^{N+2\alpha}}dy=c_1x_1^{\tau-2\alpha}(C(\tau)+cx_1^{2\alpha}+ o(x_1^{2\alpha})).
\end{eqnarray}

Continuing with our analysis we estimate $E_1(x_1)$. 
We only consider the 


 term $I_1(y)$, since the estimate for $I_1(-y)$ is similar. 
We have
\begin{eqnarray*}
 \int_{Q_{\eta}} \frac{I_1(y)}{|y|^{N+2\alpha}}dy
=
-\int_{B_\eta}\int^{\varphi(y')-x_1}_{-x_1}\frac{|x_1+y_1|^\tau}{|y|^{N+2\alpha}}dy_1dy'
 = -x_1^{\tau-2\alpha}F_1(x_1),\label{F1}



\end{eqnarray*}
where
\begin{eqnarray}\label{intF1}
F_1(x_1)= \int_{B_\frac{\eta}{x_1}}\int^{\frac{\varphi(x_1z')}{x_1}}_{0}
\frac{|z_1|^\tau}{((z_1-1)^2+|z'|^2)^{(N+2\alpha)/2}}dz_1dz'.
\end{eqnarray}
In what follows we write $\varphi_-(y')=\min\{\varphi(y'),0\}$ and $\varphi_+(y')=\varphi(y')-\varphi_-(y')$. Next we see that assuming that $0\le \varphi_+(y')\le C|y'|^2$ for $|y'|\le \eta$, for given $(z_1,z')$ satisfying $0\le z_1\le \frac{\varphi_+(x_1 z')}{x_1}$ and $|z'|\le\frac{\eta}{x_1}$ then 
\begin{eqnarray}
\label{cota}(1-z_1)^2+|z'|^2\ge \frac{1}{4}(1+|z'|^2),
\end{eqnarray}
if we assume $\eta$ small enough. Thus
\begin{eqnarray*}
F_1(x_1)&\le&C \int_{B_\frac{\eta}{x_1}}\int^{\frac{\varphi_+(x_1z')}{x_1}}_{0}
\frac{|z_1|^\tau}{(1+|z'|^2)^{(N+2\alpha)/2}}dz_1dz'\\
&\le&  Cx_1^{\tau+1}   \int_{B_\frac{\eta}{x_1}} \frac{|z'|^{2(\tau+1)}}{(1+|z'|^2)^{(N+2\alpha)/2}}dz' \\
&\le &Cx_1^{\tau+1}(x_1^{-2\tau+2\alpha-1}+1)\le Cx_1^{\min\{\tau+1,2\alpha-\tau\}}.
\end{eqnarray*}
Thus we have obtained
\begin{equation}\label{E1(x1)}
E_1(x_1)\ge -Cx_1^{\tau-2\alpha}x_1^{\min\{\tau+1,2\alpha-\tau\}}.
\end{equation}
We continue with 
the estimate  of $E_2(x_1)$.   
As before we 

only consider the term $I_2(y)$,
\begin{eqnarray}
\int_{Q_{\eta}} \frac{I_2(y)}{|y|^{N+2\alpha}}dy&=&\int_{B_\eta}\int_{\varphi(y')-x_1}^{\eta-x_1}\frac{|x_1+y_1-\varphi(y')|^{\tau}-|x_1+y_1|^{\tau}}
{(y_1^2+|y'|^2)^{\frac{N+2\alpha}2}}dy_1dy' \nonumber \\
&\ge&\int_{B_\eta}\int_{\varphi_-(y')-x_1}^{\eta-x_1}\frac{|x_1+y_1-\varphi_-(y')|^{\tau}-|x_1+y_1|^{\tau}}
{(y_1^2+|y'|^2)^{\frac{N+2\alpha}2}}dy_1dy'\nonumber \\
&=&\int_{B_\eta}\int_{\varphi_-(y')}^{\eta}\frac{|z_1-\varphi_-(y')|^{\tau}-|z_1|^{\tau}}
{((z_1-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2}}dz_1dy'\nonumber \\
&\ge&\int_{B_\eta}\int_{0}^{\eta}\frac{|z_1-\varphi_-(y')|^{\tau}-|z_1|^{\tau}}
{((z_1-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2}}dz_1dy' \nonumber \\
& &+ \int_{B_\eta}\int_{\varphi_-(y')}^{0}\frac{-|z_1|^{\tau}}
{((z_1-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2}}dz_1dy'\nonumber\\ &=&
E_{21}(x_1)+E_{22}(x_1).\label{E2cota1}
\end{eqnarray}
We observe that $E_{22}(x_1)$ is similar to $F_1(x_1)$. In order to estimate  $E_{21}(x_1)$ we use integration by parts
\begin{eqnarray*}
E_{21}(x_1)&=&
\frac1{\tau+1}\int_{B_\eta} \left\{\frac{(\eta-\varphi_-(y'))^{\tau+1}-\eta^{\tau+1}}
{((\eta-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2}}    -\frac{(-\varphi_-(y'))^{\tau +1}}{(x_1^2+|y'|^2)^{\frac{N+2\alpha}{2}}} \right\}  dy'\\
&+&
\frac{N+2\alpha}{\tau+1}\int_{B_\eta}\int_{0}^{\eta}\frac{(z_1-\varphi_-(y'))^{\tau+1}-(z_1)^{\tau+1} }
{((z_1-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2+1}}(z_1-x_1)dz_1dy'\\
&=& A_1+A_2.
\end{eqnarray*}
For the first integral we have
\begin{eqnarray*}
A_1&\ge& 
\frac1{\tau+1}\int_{B_\eta} \left\{\frac{-\eta^{\tau+1}}
{((\eta-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2}}    -\frac{(-\varphi_-(y'))^{\tau +1}}{(x_1^2+|y'|^2)^{\frac{N+2\alpha}{2}}} \right\}  dy'
\\
&\ge &
-C(\eta)-C\int_{B_\eta}\frac{|y'|^{2\tau+2}}{(x_1^{2}+|y'|^2)^{\frac{N+2\alpha}2}}dy'
\ge -Cx_1^{\tau-2\alpha+\tau+1} -C.
\end{eqnarray*}
For the second integral, since $\tau\in(-1,0)$ and
$(z_1-\varphi_-(y'))^{\tau+1} -|z_1|^{\tau+1}>0$,  we have that
\begin{eqnarray}\label{q 3.24}
A_2&\ge&\frac{N+2\alpha}{\tau+1}\int_{B_\eta}\int^{x_1}_0\frac{(z_1-\varphi_-(y'))^{\tau+1}
-|z_1|^{\tau+1}}{((z_1-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2+1}}(z_1-x_1)dz_1dy'
\nonumber 
\\[4mm]&\ge&\frac{N+2\alpha}{(\tau+1)^2}\int_{B_\eta}\int^{x_1}_0\frac{-\varphi_-(y')z_1^\tau}{((z_1-x_1)^2+|y'|^2)^{\frac{N+2\alpha}2+1}}(z_1-x_1)dz_1dy'
\nonumber
\\[4mm]&\ge&C_3x_1^{2\tau-2\alpha+1}\int_{B_{\eta/x_1}}\int^{1}_0\frac{|z'|^2z_1^\tau}{((z_1-1)^2+|z'|^2)^{\frac{N+2\alpha}2+1}}(z_1-1)dz_1dz'
\nonumber
\\[4mm]&\ge&-C_4x_1^{2\tau-2\alpha+1},
\end{eqnarray}
where $C_3,C_4>0$ independent of $x_1$ and the second inequality
used $a=z_1$ and $b=-\varphi_-(y')$ in the fact that
$(a+b)^{\tau+1}-a^{\tau+1}\le\frac{a^\tau b}{\tau+1}$ for
$a>0,b\ge0$.



 Thus, we have obtained
\begin{equation}\label{E2(x1)}
E_2(x_1)\ge -Cx_1^{\tau-2\alpha}x_1^{\min\{\tau+1,2\alpha-\tau\}}.
\end{equation}



The next step is to obtain the other inequality for $E(x_1)$. By choosing $\delta$ smaller if necessary, we can prove that
\begin{lema}\label{lemaest}
Under the regularity conditions on the boundary and with the arrangements given at the beginning of the proof, there is $\eta>0$ and $C>0$ such that
$$
d(z)\ge (z_1-\varphi(z'))(1-C|z'|^2)\quad \mbox{for all } (z_1,z')\in \Omega\cap Q_\eta.
$$
\end{lema}

\noindent

Define
\begin{equation}\label{UUWW}
U_\mu(x)=\mu V_\tau(x) \quad \mbox{and}\quad \ W_{\mu}(x)=\mu V_\tau(x),
\end{equation}
with $\tau=-\frac{2\alpha}{p-1}$. We observe  that $\tau=-\frac{2\alpha}{p-1}\in (-1,\tau_0(\alpha))$
 and $\tau p=\tau-2\alpha $, 
Then by Proposition  \ref{lm 3.3.1} and $(H2)$ we find that for $x \in A_\delta$ and $\delta>0$ small
\begin{eqnarray*}
(-\Delta)^\alpha U_\mu(x)+U^p_\mu(x)-f(x)\geq -C\mu
d(x)^{\tau-2\alpha}+\mu^p d(x)^{\tau
p}-Cd(x)^{\tau p},
\end{eqnarray*} for some $C>0$. Then there exists a large $\mu>0$ such that $U_\mu$ is a 
super-solution  of (\ref{eteo1})  with the first equation in  $A_\delta$ with the desired asymptotic behavior.
Now  by Proposition  \ref{lm 3.3.1} we have that for $x \in A_\delta$ and $\delta>0$ small
\begin{eqnarray*}
(-\Delta)^\alpha W_\mu(x)+W^p_\mu(x)-f(x)\leq -\frac{\mu}{C}
d(x)^{\tau-2\alpha}+\mu^p d(x)^{\tau p}-f(x)\leq 0,
\end{eqnarray*}
in the last inequality we have used $(H2)$ and $\mu>0$ small.  Then, by Theorem \ref{th 3.2.4} there exists a solution, with the desired asymptotic behavior. $\Box$

\label{RQQQ}
In order to obtain the above existence results  for classical solution to (\ref{3.1.1}), that is when $g$ is not necessarily zero, we only need use them with $F$ as a right hand side as given in (\ref{F}). Here we only need to assume that $g$ satisfies  $(H4)$. 
In fact, as above we find super and sub-solutions  for (\ref{eteo1}),  with $f$ replaced by $F$.  Then, as in the proof of  Theorem \ref{th 3.2.4},  we find a viscosity solution of (\ref{eteo1}) and then  $v=u+\tilde g$ is a viscosity solution of (\ref{3.1.1}).  Next we use Theorem 2.6 in  \cite{CS2} and then we use  Theorem \ref{regularity} to obtain that $v$ is a classical solution of (\ref{3.1.1}).\\

